static decimal CalculateVariance(decimal recordedHours, decimal scheduledHours)
{
    decimal difference = recordedHours - scheduledHours;
    return difference;
}

static string ClassifyVariance(decimal varianceHours)
{
    return varianceHours switch
    {
        > 0m => "over schedule",
        < 0m => "under schedule",
        _ => "on schedule"
    };
}
